@pytest.mark.parametrize("dynamic", [False, True])
def test_custom_version_option(runner, dynamic):
    text = "Example 1.2\nDependency 3.4 (100%)"
    version = (lambda: text) if dynamic else text

    @click.command()
    @click.custom_version_option(version)
    @click.argument("required")
    def cli(required):
        pytest.fail("The command must not run.")

    result = runner.invoke(cli, ["--version"])
