    assert result.output == f"{text}\n"


def test_custom_version_option_callable_is_lazy(runner):
    calls = []

    def version():
        calls.append(click.get_current_context().info_name)
        return f"Version {len(calls)}"

    @click.command()
    @click.custom_version_option(version)
    def cli():
        click.echo("Running")

    result = runner.invoke(cli, [])
    assert result.exit_code == 0
    assert result.output == "Running\n"
