import json


# Add alongside the existing shell source templates.
_SOURCE_POWERSHELL = r"""
Register-ArgumentCompleter -Native -CommandName '%(prog_name)s' -ScriptBlock {
    param($wordToComplete, $commandAst, $cursorPosition)

    $arguments = @()

    foreach ($element in $commandAst.CommandElements | Select-Object -Skip 1) {
        if ($element.Extent.EndOffset -ge $cursorPosition) {
            break
        }

        if ($element -is [System.Management.Automation.Language.StringConstantExpressionAst] -or
            $element -is [System.Management.Automation.Language.ExpandableStringExpressionAst]) {
            $arguments += $element.Value
        } else {
            $arguments += $element.Extent.Text
        }
    }

    # Decode quoting without evaluating expressions in the command line.
    $incomplete = $wordToComplete
    $tokens = $null
    $parseErrors = $null
    $wordAst = [System.Management.Automation.Language.Parser]::ParseInput(
        $wordToComplete, [ref]$tokens, [ref]$parseErrors
    )
    $wordElement = $wordAst.Find({
        param($node)
        $node -is [System.Management.Automation.Language.CommandAst]
    }, $true)

    if ($null -ne $wordElement -and $wordElement.CommandElements.Count -eq 1) {
        $element = $wordElement.CommandElements[0]

        if ($element -is [System.Management.Automation.Language.StringConstantExpressionAst] -or
            $element -is [System.Management.Automation.Language.ExpandableStringExpressionAst]) {
            $incomplete = $element.Value
        }
    }

    $request = @{
        args = @($arguments)
        incomplete = $incomplete
    } | ConvertTo-Json -Compress

    $savedInstruction = [Environment]::GetEnvironmentVariable(
        '%(complete_var)s', 'Process'
    )
    $savedArguments = [Environment]::GetEnvironmentVariable(
        '_CLICK_POWERSHELL_COMPLETE_ARGS', 'Process'
    )

    try {
        [Environment]::SetEnvironmentVariable(
            '%(complete_var)s', 'powershell_complete', 'Process'
        )
        [Environment]::SetEnvironmentVariable(
            '_CLICK_POWERSHELL_COMPLETE_ARGS', $request, 'Process'
        )
        $lines = @(& '%(prog_name)s')
    } finally {
        [Environment]::SetEnvironmentVariable(
            '%(complete_var)s', $savedInstruction, 'Process'
        )
        [Environment]::SetEnvironmentVariable(
            '_CLICK_POWERSHELL_COMPLETE_ARGS', $savedArguments, 'Process'
        )
    }

    foreach ($line in $lines) {
        try {
            $item = $line | ConvertFrom-Json -ErrorAction Stop
        } catch {
            continue
        }

        if ($item.type -eq 'file' -or $item.type -eq 'dir') {
            foreach ($result in [System.Management.Automation.CompletionCompleters]::CompleteFilename($item.value)) {
                if ($item.type -eq 'file' -or
                    $result.ResultType -eq [System.Management.Automation.CompletionResultType]::ProviderContainer) {
                    $result
                }
            }

            continue
        }

        if ([string]::IsNullOrEmpty($item.value)) {
            continue
        }

        $helpText = $item.help

        if ([string]::IsNullOrEmpty($helpText)) {
            $helpText = $item.value
        }

        $completionText = "'" + $item.value.Replace("'", "''") + "'"
        [System.Management.Automation.CompletionResult]::new(
            $completionText, $item.value,
            [System.Management.Automation.CompletionResultType]::ParameterValue,
            $helpText
        )
    }
}
"""


# Add before the built-in shell registry.
class PowerShellComplete(ShellComplete):
    """Shell completion for PowerShell."""

    name: t.ClassVar[str] = "powershell"
    source_template: t.ClassVar[str] = _SOURCE_POWERSHELL

    def source_vars(self) -> _SourceVarsDict:
        values = super().source_vars()
        values["prog_name"] = values["prog_name"].replace("'", "''")
        values["complete_var"] = values["complete_var"].replace("'", "''")
        return values

    def get_completion_args(self) -> tuple[list[str], str]:
        data = json.loads(os.environ["_CLICK_POWERSHELL_COMPLETE_ARGS"])
        return data["args"], data["incomplete"]

    def format_completion(self, item: CompletionItem[str]) -> str:
        return json.dumps(
            {"type": item.type, "value": item.value, "help": item.help}
        )


