import click
from click.shell_completion import CompletionItem
from click.shell_completion import get_completion_class
from click.shell_completion import PowerShellComplete
from click.testing import CliRunner


def test_registered():
    assert get_completion_class("powershell") is PowerShellComplete


@pytest.mark.parametrize(
    ("args", "incomplete"),
    [
        ([], ""),
        (["subcommand", "two words"], "snowman ☃"),
        (["", "a'b", 'a"b', "C:\\some path\\"], "$literal"),
    ],
)
def test_completion_args(monkeypatch, args, incomplete):
    monkeypatch.setenv(
        "_CLICK_POWERSHELL_COMPLETE_ARGS",
        json.dumps({"args": args, "incomplete": incomplete}),
    )
    comp = PowerShellComplete(click.Command("cli"), {}, "cli", "_CLI_COMPLETE")
    assert comp.get_completion_args() == (args, incomplete)


@pytest.mark.parametrize("type_", ["plain", "file", "dir"])
@pytest.mark.parametrize("help_", [None, "Help with\na newline and a tab\t☃"])
def test_format_completion(type_, help_):
    comp = PowerShellComplete(click.Command("cli"), {}, "cli", "_CLI_COMPLETE")
    value = "a'b\"c\n☃"
    result = comp.format_completion(CompletionItem(value, type=type_, help=help_))
    assert len(result.splitlines()) == 1
    assert json.loads(result) == {
        "type": type_, "value": value, "help": help_
    }


def test_complete_instruction():
    @click.command()
    @click.argument("value", type=click.Choice(["two words", "snowman ☃"]))
    def cli(value):
        pass

    result = CliRunner().invoke(
        cli,
        [],
        prog_name="example",
        env={
            "_EXAMPLE_COMPLETE": "powershell_complete",
            "_CLICK_POWERSHELL_COMPLETE_ARGS": json.dumps(
                {"args": [], "incomplete": "two"}
            ),
        },
    )
    assert result.exit_code == 0, result.output
    assert json.loads(result.output) == {
        "type": "plain", "value": "two words", "help": None
    }


def test_source_quoting():
    comp = PowerShellComplete(
        click.Command("cli"), {}, "some'command", "_SOME'COMMAND_COMPLETE"
    )
    source = comp.source()
    assert "-CommandName 'some''command'" in source
    assert "& 'some''command'" in source
    assert "'_SOME''COMMAND_COMPLETE'" in source


