import json


# Add before the built-in shell registry.
_SOURCE_POWERSHELL = r"""
Register-ArgumentCompleter -Native -CommandName '%(prog_name)s' -ScriptBlock {
    param($wordToComplete, $commandAst, $cursorPosition)

    $arguments = @()
    $incomplete = $wordToComplete

    foreach ($element in @($commandAst.CommandElements | Select-Object -Skip 1)) {
        if ($element.Extent.StartOffset -ge $cursorPosition) {
            break
        }

        if ($element.Extent.EndOffset -ge $cursorPosition) {
            $prefix = $element.Extent.Text.Substring(
                0, $cursorPosition - $element.Extent.StartOffset
            )
            $tokens = $null
            $parseErrors = $null
            $null = [System.Management.Automation.Language.Parser]::ParseInput(
                $prefix, [ref]$tokens, [ref]$parseErrors
            )

            if ($tokens.Count -gt 0 -and
                $tokens[0] -is [System.Management.Automation.Language.StringToken]) {
                $incomplete = $tokens[0].Value
            }

            break
        }

        if ($element -is [System.Management.Automation.Language.StringConstantExpressionAst] -or
            $element -is [System.Management.Automation.Language.ExpandableStringExpressionAst]) {
            $arguments += $element.Value
        } else {
            $arguments += $element.Extent.Text
        }
    }

    $saved = @{}
    foreach ($name in @('%(complete_var)s', 'COMP_WORDS', 'COMP_INCOMPLETE')) {
        $saved[$name] = [Environment]::GetEnvironmentVariable($name, 'Process')
    }

    try {
        [Environment]::SetEnvironmentVariable(
            '%(complete_var)s', 'powershell_complete', 'Process'
        )
        $env:COMP_WORDS = ConvertTo-Json -InputObject $arguments -Compress
        $env:COMP_INCOMPLETE = $incomplete
        $response = & '%(prog_name)s'
    } finally {
        foreach ($name in $saved.Keys) {
            [Environment]::SetEnvironmentVariable($name, $saved[$name], 'Process')
        }
    }

    foreach ($line in $response) {
        if ([string]::IsNullOrWhiteSpace($line)) {
            continue
        }

        $item = ConvertFrom-Json -InputObject $line -ErrorAction Stop

        if ($item.type -eq 'file' -or $item.type -eq 'dir') {
            foreach ($result in [System.Management.Automation.CompletionCompleters]::CompleteFilename($item.value)) {
                if ($item.type -eq 'file' -or
                    $result.ResultType -eq [System.Management.Automation.CompletionResultType]::ProviderContainer) {
                    $result
                }
            }

            continue
        }

        $value = [string]$item.value
        if ($value.Length -eq 0) {
            continue
        }

        $completionText = "'" + $value.Replace("'", "''") + "'"
        $tooltip = if ($item.help) { [string]$item.help } else { $value }
        [System.Management.Automation.CompletionResult]::new(
            $completionText,
            $value,
            [System.Management.Automation.CompletionResultType]::ParameterValue,
            $tooltip
        )
    }
}
"""


class PowerShellComplete(ShellComplete):
    """Shell completion for PowerShell 7 and newer."""

    name: t.ClassVar[str] = "powershell"
    source_template: t.ClassVar[str] = _SOURCE_POWERSHELL

    def source_vars(self) -> _SourceVarsDict:
        rv = super().source_vars()
        # These values occur inside PowerShell single-quoted strings.
        rv["prog_name"] = rv["prog_name"].replace("'", "''")
        rv["complete_var"] = rv["complete_var"].replace("'", "''")
        return rv

    def get_completion_args(self) -> tuple[list[str], str]:
        args = json.loads(os.environ["COMP_WORDS"])
        return args, os.environ.get("COMP_INCOMPLETE", "")

    def format_completion(self, item: CompletionItem[str]) -> str:
        return json.dumps(
            {"type": item.type, "value": item.value, "help": item.help}
        )


# Add the powershell entry to the existing registry.
_available_shells: dict[str, type[ShellComplete]] = {
    "bash": BashComplete,
    "zsh": ZshComplete,
    "fish": FishComplete,
    "powershell": PowerShellComplete,
}

