import pytest

from click.testing import CliRunner


@pytest.mark.parametrize("keep_directory", [False, True])
@pytest.mark.parametrize("raise_error", [False, True])
def test_isolated_filesystem_deprecated(tmp_path, keep_directory, raise_error):
    runner = CliRunner()
    original_cwd = os.getcwd()
    temp_dir = tmp_path if keep_directory else None

    class ContextError(Exception):
        pass

    with pytest.warns(
        DeprecationWarning, match="CliRunner.isolated_filesystem.*deprecated"
    ) as recorded:
        try:
            with runner.isolated_filesystem(temp_dir) as directory:
                created = Path(directory)
                assert Path.cwd() == created.resolve()
                (created / "example.txt").write_text("example", encoding="utf-8")

                if raise_error:
                    raise ContextError
        except ContextError:
            assert raise_error
        else:
            assert not raise_error

    assert len(recorded) == 1
    assert recorded[0].filename == __file__
    assert os.getcwd() == original_cwd

    if keep_directory:
        assert created.parent == tmp_path
        assert (created / "example.txt").read_text(encoding="utf-8") == "example"
    else:
        assert not created.exists()


