def _tempfilepager(
    cmd: list[str], color: bool | None
) -> t.ContextManager[tuple[t.BinaryIO | t.TextIO, str, bool]]:
    import subprocess
    import tempfile

    from ._compat import get_best_encoding

    @contextlib.contextmanager
    def pager() -> t.Iterator[tuple[t.BinaryIO | t.TextIO, str, bool]]:
        encoding = get_best_encoding(sys.stdout)
        file = tempfile.NamedTemporaryFile(
            mode="w", encoding=encoding, delete=False
        )
        try:
            # Close the file before running the pager or removing it. Windows
            # cannot remove an open file, including when the caller raises.
            with file:
                yield file, encoding, bool(color)

            try:
                subprocess.call([*cmd, file.name])
            except KeyboardInterrupt:
                pass
        finally:
            os.unlink(file.name)

    return pager()

