    monkeypatch, tmp_path, use_pager_file
):
    import subprocess
    import tempfile

    from click import _termui_impl
    from click.testing import CliRunner

    monkeypatch.setattr(tempfile, "tempdir", str(tmp_path))
    monkeypatch.setattr(
        _termui_impl,
        "_pager_contextmanager",
        lambda color=None: _termui_impl._tempfilepager(["more"], color),
    )

    def unexpected_pager(*args, **kwargs):
        pytest.fail("The pager must not start after an error generating output.")

    monkeypatch.setattr(subprocess, "call", unexpected_pager)

