import hashlib

import pytest

from requests.auth import HTTPDigestAuth


@pytest.mark.parametrize(
    "algorithm, hash_name",
    [
        (None, "md5"),
        ("MD5", "md5"),
        ("MD5-SESS", "md5"),
        ("SHA", "sha1"),
        ("SHA-256", "sha256"),
        ("SHA-512", "sha512"),
    ],
)
@pytest.mark.parametrize("qop", [None, "auth"])
def test_digest_auth_hashes_allow_nonsecurity_use(
    monkeypatch, algorithm, hash_name, qop
):
    monkeypatch.setattr("requests.auth.os.urandom", lambda size: b"x" * size)
    monkeypatch.setattr("requests.auth.time.ctime", lambda: "fixed time")

    def build_header():
        auth = HTTPDigestAuth("user", "password")
        auth.init_per_thread_state()
        auth._thread_local.chal = {
            "realm": "realm",
            "nonce": "nonce",
            "algorithm": algorithm,
            "qop": qop,
        }
        return auth.build_digest_header("GET", "https://example.com/path?key=value")

    expected = build_header()
    calls = []

    def wrap_hash(name):
        original = getattr(hashlib, name)

        def checked_hash(data, *, usedforsecurity):
            assert usedforsecurity is False
            calls.append(name)
            return original(data, usedforsecurity=usedforsecurity)

        return checked_hash

    for name in ("md5", "sha1", "sha256", "sha512"):
        monkeypatch.setattr(hashlib, name, wrap_hash(name))

    assert build_header() == expected
    expected_calls = [hash_name, hash_name, "sha1"]
    if algorithm == "MD5-SESS":
        expected_calls.append(hash_name)
    expected_calls.append(hash_name)
    assert calls == expected_calls

