@pytest.mark.parametrize("position", [0, 3])
def test_prepare_body_delegating_file_wrapper(self, position):
    from io import BytesIO

    from requests import Request
    from requests.utils import rewind_body

    class FileWrapper:
        def __init__(self, stream):
            self.stream = stream

        def __getattr__(self, name):
            return getattr(self.stream, name)

    body = FileWrapper(BytesIO(b"example"))
    body.seek(position)
    prepared = Request("POST", "https://example.com", data=body).prepare()

    assert prepared.body is body
    assert prepared.headers["Content-Length"] == str(7 - position)
    assert "Transfer-Encoding" not in prepared.headers
    assert "Content-Type" not in prepared.headers
    assert prepared._body_position == position

    assert body.read() == b"example"[position:]
    rewind_body(prepared)
    assert body.tell() == position
    assert body.read() == b"example"[position:]

