from io import BytesIO

import pytest

from requests.models import RequestEncodingMixin


@pytest.mark.parametrize("tuple_size", [None, 2, 3, 4])
def test_encode_files_with_getattr_wrapper(tuple_size):
    class FileWrapper:
        def __init__(self, fileobj):
            self.fileobj = fileobj

        def __getattr__(self, name):
            return getattr(self.fileobj, name)

    payload = b"wrapped file contents"
    fileobj = BytesIO(payload)
    fileobj.name = "upload.txt"
    wrapper = FileWrapper(fileobj)

    if tuple_size is None:
        value = wrapper
        filename = "upload.txt"
    else:
        value = (
            "explicit.txt",
            wrapper,
            "application/octet-stream",
            {"X-Upload": "wrapped"},
        )[:tuple_size]
        filename = "explicit.txt"

    body, content_type = RequestEncodingMixin._encode_files(
        {"file": value}, {"description": "example"}
    )

    assert content_type.startswith("multipart/form-data; boundary=")
    assert (
        f'Content-Disposition: form-data; name="file"; filename="{filename}"'.encode()
        in body
    )
    assert b"\r\n\r\n" + payload + b"\r\n" in body
    assert b'name="description"\r\n\r\nexample\r\n' in body
    assert fileobj.tell() == len(payload)
    if tuple_size in (3, 4):
        assert b"Content-Type: application/octet-stream\r\n" in body
    if tuple_size == 4:
        assert b"X-Upload: wrapped\r\n" in body

