func TestPowerShellCompletionLanguageModes(t *testing.T) {
	powershell, err := exec.LookPath("pwsh")
	if err != nil {
		powershell, err = exec.LookPath("powershell")
		if err != nil {
			t.Skip("PowerShell is not installed")
		}
	}

	for _, mode := range []string{"FullLanguage", "ConstrainedLanguage"} {
		t.Run(mode, func(t *testing.T) {
			var script bytes.Buffer
			script.WriteString(`
$ErrorActionPreference = 'Stop'
function Register-ArgumentCompleter {
    param($CommandName, $ScriptBlock)
    $script:TestCompleter = $ScriptBlock
}
function Get-PSReadLineKeyHandler {
    New-Object -TypeName PSObject -Property @{Key='Tab'; Function='MenuComplete'}
}
function cobra_constrained_test {
    "--zeta` + "`t" + `Last result"
    "--alpha value` + "`t" + `First result"
    ':4'
}
`)
			genPowerShellComp(&script, "cobra_constrained_test", true)
			script.WriteString(`
$command = 'cobra_constrained_test -'
$commandAst = New-Object -TypeName PSObject -Property @{CommandElements=@('cobra_constrained_test', '-')}
$cursorPosition = $command.Length
$ExecutionContext.SessionState.LanguageMode = '` + mode + `'
$results = @(& $script:TestCompleter '-' $commandAst $cursorPosition)
if ($results.Count -ne 2) {
    throw "Expected two completions, got $($results.Count)"
}
$expected = @('--alpha` + "`" + ` value ', '--zeta ')
for ($i = 0; $i -lt $results.Count; $i++) {
    if ($ExecutionContext.SessionState.LanguageMode -eq 'ConstrainedLanguage') {
        if ($results[$i] -isnot [string]) {
            throw 'Expected a string completion in constrained language mode'
        }
        $actual = $results[$i]
    } else {
        if ($results[$i] -isnot [System.Management.Automation.CompletionResult]) {
            throw 'Expected a CompletionResult in full language mode'
        }
        $actual = $results[$i].CompletionText
    }
    if ($actual -cne $expected[$i]) {
        throw "Unexpected completion: [$actual], expected [$($expected[$i])]"
    }
}
`)
			path := filepath.Join(t.TempDir(), "completion.ps1")
			if err := os.WriteFile(path, script.Bytes(), 0600); err != nil {
				t.Fatal(err)
			}
			cmd := exec.Command(powershell, "-NoLogo", "-NoProfile", "-NonInteractive", "-ExecutionPolicy", "Bypass", "-File", path)
			if output, err := cmd.CombinedOutput(); err != nil {
				t.Fatalf("PowerShell completion failed: %v\n%s", err, output)
			}
		})
	}
}

