func TestCompletionForAlreadySetMultiValueFlags(t *testing.T) {
	tests := []struct {
		name     string
		register func(*pflag.FlagSet)
		want     bool
	}{
		{
			name: "custom value with GetSlice",
			register: func(flags *pflag.FlagSet) {
				flags.VarP(&completionMultiValue{}, "value", "v", "test value")
			},
			want: true,
		},
		{
			name: "string slice",
			register: func(flags *pflag.FlagSet) {
				flags.StringSliceP("value", "v", nil, "test value")
			},
			want: true,
		},
		{
			name: "string array",
			register: func(flags *pflag.FlagSet) {
				flags.StringArrayP("value", "v", nil, "test value")
			},
			want: true,
		},
		{
			name: "string map",
			register: func(flags *pflag.FlagSet) {
				flags.StringToStringP("value", "v", nil, "test value")
			},
			want: true,
		},
		{
			name: "scalar",
			register: func(flags *pflag.FlagSet) {
				flags.StringP("value", "v", "", "test value")
			},
			want: false,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			for _, prefix := range []string{"--", "-v"} {
				t.Run(prefix, func(t *testing.T) {
					cmd := &Command{
						Use: "test",
						Run: func(*Command, []string) {},
					}
					tt.register(cmd.Flags())

					_, completions, _, err := cmd.getCompletions([]string{"--value=first=one", prefix})
					if err != nil {
						t.Fatal(err)
					}
					if !cmd.Flags().Lookup("value").Changed {
						t.Fatal("expected value flag to have been set")
					}

					name := "--value"
					if prefix == "-v" {
						name = "-v"
					}
					found := false
					for _, completion := range completions {
						if strings.SplitN(completion, "\t", 2)[0] == name {
							found = true
							break
						}
					}
					if found != tt.want {
						t.Errorf("completion for %q present = %v, want %v; completions: %v", name, found, tt.want, completions)
					}
				})
			}
		})
	}
}

