			completion: NoFileCompletions,
			directive:  ShellCompDirectiveNoFileComp,
		},
		{
			name:       "fixed choices",
			completion: FixedCompletions([]string{"first", "second"}, ShellCompDirectiveNoFileComp),
			want:       []string{"first", "second"},
			directive:  ShellCompDirectiveNoFileComp,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			cmd := &Command{Use: "test", ValidArgsFunction: tt.completion}
			cmd.Flags().String("value", "", "value to complete")
			if err := cmd.RegisterFlagCompletionFunc("value", tt.completion); err != nil {
				t.Fatal(err)
			}

			completion, ok := cmd.GetFlagCompletionFunc("value")
			if !ok || completion == nil {
				t.Fatal("expected a registered completion function")
			}

			for _, f := range []CompletionFunc{cmd.ValidArgsFunction, completion} {
				got, directive := f(cmd, nil, "")
				if directive != tt.directive {
					t.Errorf("directive = %v, want %v", directive, tt.directive)
				}
				if len(got) != len(tt.want) {
					t.Fatalf("completions = %v, want %v", got, tt.want)
				}
				for i := range got {
					if got[i] != tt.want[i] {
						t.Errorf("completion[%d] = %q, want %q", i, got[i], tt.want[i])
					}
				}
			}
		})
	}
}

// CompletionFunc is a function that provides shell completions for command arguments
// or flag values. It can be used with Command.ValidArgsFunction and
// Command.RegisterFlagCompletionFunc.
type CompletionFunc func(cmd *Command, args []string, toComplete string) ([]string, ShellCompDirective)

// Change the existing flagCompletionFunctions initializer to:
flagCompletionFunctions = map[*pflag.Flag]CompletionFunc{}

// NoFileCompletions disables file completion. It can be used with
// Command.ValidArgsFunction and Command.RegisterFlagCompletionFunc.
func NoFileCompletions(cmd *Command, args []string, toComplete string) ([]string, ShellCompDirective) {
	return nil, ShellCompDirectiveNoFileComp
}

// FixedCompletions returns a completion function that always returns the given
// choices and directive. It can be used with Command.ValidArgsFunction and
// Command.RegisterFlagCompletionFunc.
func FixedCompletions(choices []string, directive ShellCompDirective) CompletionFunc {
	return func(cmd *Command, args []string, toComplete string) ([]string, ShellCompDirective) {
		return choices, directive
	}
}

// RegisterFlagCompletionFunc registers a function to provide completions for a flag.
func (c *Command) RegisterFlagCompletionFunc(flagName string, f CompletionFunc) error {
	flag := c.Flag(flagName)
	if flag == nil {
		return fmt.Errorf("RegisterFlagCompletionFunc: flag '%s' does not exist", flagName)
	}
	flagCompletionMutex.Lock()
	defer flagCompletionMutex.Unlock()

	if _, exists := flagCompletionFunctions[flag]; exists {
		return fmt.Errorf("RegisterFlagCompletionFunc: flag '%s' already registered", flagName)
	}
	flagCompletionFunctions[flag] = f
	return nil
}

// GetFlagCompletionFunc returns the completion function registered for a flag,
// and whether a function was registered.
func (c *Command) GetFlagCompletionFunc(flagName string) (CompletionFunc, bool) {
	flag := c.Flag(flagName)
	if flag == nil {
		return nil, false
	}

	flagCompletionMutex.RLock()
	defer flagCompletionMutex.RUnlock()

	completionFunc, exists := flagCompletionFunctions[flag]
	return completionFunc, exists
}

func TestCompletionFuncHelpers(t *testing.T) {
	tests := []struct {
		name      string
		completion CompletionFunc
		want      []string
		directive ShellCompDirective
	}{
		{
