	"testing"
)

func TestBashCompletionV2WhitespaceArguments(t *testing.T) {
	bash, err := exec.LookPath("bash")
	if err != nil {
		t.Skip("bash is not available")
	}

	tests := []struct {
		name  string
		setup string
		want  string
	}{
		{
			name:  "space in current argument",
			setup: "words=(cobra_whitespace_test 'two words'); cur='two words'",
			want:  "<two words>\n",
		},
		{
			name:  "tabs and newlines",
			setup: "words=(cobra_whitespace_test $'two\\twords\\nmore'); cur=${words[1]}",
			want:  "<two\twords\nmore>\n",
		},
		{
			name:  "completed argument followed by empty word",
			setup: "words=(cobra_whitespace_test 'two words' ''); cur=''",
			want:  "<two words>\n<>\n",
		},
		{
			name:  "completed argument without empty word",
			setup: "words=(cobra_whitespace_test 'two words'); cur=''",
			want:  "<two words>\n<>\n",
		},
		{
			name:  "empty argument before current argument",
			setup: "words=(cobra_whitespace_test '' 'two words'); cur='two words'",
			want:  "<>\n<two words>\n",
		},
		{
			name:  "flag with equals and whitespace",
			setup: "words=(cobra_whitespace_test '--name=two words'); cur='--name=two words'",
			want:  "<--name=two words>\n",
		},
		{
			name:  "empty flag value",
			setup: "words=(cobra_whitespace_test '--name='); cur=''",
			want:  "<--name=>\n",
		},
		{
			name:  "literal shell characters",
			setup: "words=(cobra_whitespace_test 'a $HOME; $(printf injected) \\ b'); cur=${words[1]}",
			want:  "<a $HOME; $(printf injected) \\ b>\n",
		},
	}

	for _, includeDesc := range []bool{false, true} {
		requestCmd := ShellCompNoDescRequestCmd
		if includeDesc {
			requestCmd = ShellCompRequestCmd
		}
		for _, tt := range tests {
			t.Run(requestCmd+"/"+tt.name, func(t *testing.T) {
				var script bytes.Buffer
				cmd := &Command{Use: "cobra_whitespace_test"}
				if err := cmd.GenBashCompletionV2(&script, includeDesc); err != nil {
					t.Fatal(err)
				}
				script.WriteString(`
cobra_whitespace_test() {
    printf '<%s>\n' "$@"
    printf ':0'
}
`)
				script.WriteString(tt.setup)
				script.WriteString("\n__cobra_whitespace_test_get_completion_results\nprintf '%s' \"$out\"\n")

				process := exec.Command(bash, "--noprofile", "--norc")
				process.Stdin = strings.NewReader(script.String())
				var stderr bytes.Buffer
				process.Stderr = &stderr
				got, err := process.Output()
				if err != nil {
					t.Fatalf("bash failed: %v\n%s", err, stderr.String())
				}
				want := "<" + requestCmd + ">\n" + tt.want
				if string(got) != want {
					t.Fatalf("completion arguments: got %q, want %q", got, want)
				}
			})
		}
	}
}

