// Add these fields to Command, retaining the existing template string fields.
usageTemplateFunc   func(io.Writer, *Command) error
helpTemplateFunc    func(io.Writer, *Command) error
versionTemplateFunc func(io.Writer, *Command) error

// Replace the existing template setters. Keep template execution reachable only
// through these setters; default rendering must not reference tmpl.
func (c *Command) SetUsageTemplate(s string) {
	c.usageTemplate = s
	c.usageTemplateFunc = nil
	if s != "" {
		c.usageTemplateFunc = func(w io.Writer, cmd *Command) error {
			return tmpl(w, cmd.UsageTemplate(), cmd)
		}
	}
}

func (c *Command) SetHelpTemplate(s string) {
	c.helpTemplate = s
	c.helpTemplateFunc = nil
	if s != "" {
		c.helpTemplateFunc = func(w io.Writer, cmd *Command) error {
			return tmpl(w, cmd.HelpTemplate(), cmd)
		}
	}
}

func (c *Command) SetVersionTemplate(s string) {
	c.versionTemplate = s
	c.versionTemplateFunc = nil
	if s != "" {
		c.versionTemplateFunc = func(w io.Writer, cmd *Command) error {
			return tmpl(w, cmd.VersionTemplate(), cmd)
		}
	}
}

// Replace UsageFunc.
func (c *Command) UsageFunc() func(*Command) error {
	if c.usageFunc != nil {
		return c.usageFunc
	}
	if c.HasParent() {
		return c.Parent().UsageFunc()
	}
	return func(cmd *Command) error {
		cmd.mergePersistentFlags()
		return cmd.renderUsage(cmd.OutOrStderr())
	}
}

// Replace HelpFunc.
func (c *Command) HelpFunc() func(*Command, []string) {
	if c.helpFunc != nil {
		return c.helpFunc
	}
	if c.HasParent() {
		return c.Parent().HelpFunc()
	}
	return func(cmd *Command, args []string) {
		cmd.mergePersistentFlags()
		// The help should be sent to stdout.
		// See https://github.com/spf13/cobra/issues/1002.
		if err := cmd.renderHelp(cmd.OutOrStdout()); err != nil {
			cmd.PrintErrln(err)
		}
	}
}

// In execute's version-flag branch, replace:
