package cobra

import (
	"fmt"
	"io"
	"strings"
)

func (c *Command) renderUsage(w io.Writer) error {
	for cmd := c; cmd != nil; cmd = cmd.Parent() {
		if cmd.usageTemplateFunc != nil {
			return cmd.usageTemplateFunc(w, c)
		}
	}
	return defaultUsage(w, c)
}

func (c *Command) renderHelp(w io.Writer) error {
	for cmd := c; cmd != nil; cmd = cmd.Parent() {
		if cmd.helpTemplateFunc != nil {
			return cmd.helpTemplateFunc(w, c)
		}
	}
	return defaultHelp(w, c)
}

func (c *Command) renderVersion(w io.Writer) error {
	for cmd := c; cmd != nil; cmd = cmd.Parent() {
		if cmd.versionTemplateFunc != nil {
			return cmd.versionTemplateFunc(w, c)
		}
	}
	var out strings.Builder
	if name := c.Name(); name != "" {
		out.WriteString(name)
		out.WriteByte(' ')
	}
	fmt.Fprintf(&out, "version %s\n", c.Version)
	_, err := io.WriteString(w, out.String())
	return err
}

func defaultHelp(w io.Writer, c *Command) error {
	var out strings.Builder
	description := c.Long
	if description == "" {
		description = c.Short
	}
	if description != "" {
		out.WriteString(trimRightSpace(description))
		out.WriteString("\n\n")
	}
	if c.Runnable() || c.HasSubCommands() {
		// UsageString honors custom usage functions and inherited templates.
		out.WriteString(c.UsageString())
	}
	_, err := io.WriteString(w, out.String())
	return err
}

func defaultUsage(w io.Writer, c *Command) error {
	var out strings.Builder
	out.WriteString("Usage:")
	if c.Runnable() {
		fmt.Fprintf(&out, "\n  %s", c.UseLine())
	}
	if c.HasAvailableSubCommands() {
		fmt.Fprintf(&out, "\n  %s [command]", c.CommandPath())
	}
	if len(c.Aliases) > 0 {
		fmt.Fprintf(&out, "\n\nAliases:\n  %s", c.NameAndAliases())
	}
	if c.HasExample() {
		fmt.Fprintf(&out, "\n\nExamples:\n%s", c.Example)
	}
	if c.HasAvailableSubCommands() {
		commands := c.Commands()
		if c.AllChildCommandsHaveGroup() {
			for _, group := range c.Groups() {
				fmt.Fprintf(&out, "\n\n%s", group.Title)
				for _, cmd := range commands {
					if cmd.GroupID == group.ID && (cmd.IsAvailableCommand() || cmd.Name() == "help") {
						fmt.Fprintf(&out, "\n  %s %s", rpad(cmd.Name(), cmd.NamePadding()), cmd.Short)
					}
				}
			}
		} else {
			out.WriteString("\n\nAvailable Commands:")
			for _, cmd := range commands {
				if cmd.IsAvailableCommand() || cmd.Name() == "help" {
					fmt.Fprintf(&out, "\n  %s %s", rpad(cmd.Name(), cmd.NamePadding()), cmd.Short)
				}
			}
		}
	}
	if c.HasAvailableLocalFlags() {
		fmt.Fprintf(&out, "\n\nFlags:\n%s", trimRightSpace(c.LocalFlags().FlagUsages()))
	}
	if c.HasAvailableInheritedFlags() {
		fmt.Fprintf(&out, "\n\nGlobal Flags:\n%s", trimRightSpace(c.InheritedFlags().FlagUsages()))
	}
	if c.HasHelpSubCommands() {
		out.WriteString("\n\nAdditional help topics:")
		for _, cmd := range c.Commands() {
			if cmd.IsAdditionalHelpTopicCommand() {
				fmt.Fprintf(&out, "\n  %s %s", rpad(cmd.CommandPath(), cmd.CommandPathPadding()), cmd.Short)
			}
		}
	}
	if c.HasAvailableSubCommands() {
		fmt.Fprintf(&out, "\n\nUse %q for more information about a command.", c.CommandPath()+" [command] --help")
	}
	out.WriteByte('\n')
	_, err := io.WriteString(w, out.String())
	return err
}

