func TestDefaultRenderingMatchesTemplates(t *testing.T) {
	for _, name := range []string{"empty", "runnable", "commands", "groups", "mixed-groups", "child"} {
		t.Run(name, func(t *testing.T) {
			c := defaultRenderingCommand(name)
			c.mergePersistentFlags()
			for _, kind := range []string{"usage", "help", "version"} {
				t.Run(kind, func(t *testing.T) {
					var got, want bytes.Buffer
					var err error
					switch kind {
					case "usage":
						err = tmpl(&want, c.UsageTemplate(), c)
						if err == nil {
							err = c.renderUsage(&got)
						}
					case "help":
						err = tmpl(&want, c.HelpTemplate(), c)
						if err == nil {
							err = c.renderHelp(&got)
						}
					case "version":
						err = tmpl(&want, c.VersionTemplate(), c)
						if err == nil {
							err = c.renderVersion(&got)
						}
					}
					if err != nil {
						t.Fatal(err)
					}
					if got.String() != want.String() {
						t.Fatalf("output mismatch\ngot:  %q\nwant: %q", got.String(), want.String())
					}
				})
			}
		})
	}
}

func defaultRenderingCommand(kind string) *Command {
	c := &Command{Use: "app", Version: "1.2.3"}
	if kind == "empty" {
		c.Use = ""
		return c
	}
	c.Use = "app [file]"
	c.Run = func(*Command, []string) {}
	c.Aliases = []string{"application", "a"}
	c.Short = "short description"
	c.Long = "long description  \n\t"
	c.Example = "  app example"
	c.Flags().Bool("local", false, "a local flag")
	c.Flags().Bool("hidden", false, "a hidden flag")
	_ = c.Flags().MarkHidden("hidden")
	if kind == "runnable" {
		return c
	}
	c.AddGroup(&Group{ID: "main", Title: "Main Commands:"})
	child := &Command{Use: "child", Short: "child command", GroupID: "main", Run: func(*Command, []string) {}}
	c.AddCommand(child)
	c.AddCommand(&Command{Use: "hidden", Hidden: true, GroupID: "main", Run: func(*Command, []string) {}})
	c.AddCommand(&Command{Use: "old", Deprecated: "use child", GroupID: "main", Run: func(*Command, []string) {}})
	c.AddCommand(&Command{Use: "topic", Short: "additional help", GroupID: "main"})
	if kind == "commands" || kind == "mixed-groups" {
		c.AddCommand(&Command{Use: "other", Short: "other command", Run: func(*Command, []string) {}})
	}
	if kind == "child" {
		c.PersistentFlags().String("global", "", "an inherited flag")
		child.Flags().Bool("local", false, "a child flag")
		child.Short = "child description"
		child.Version = "2.0.0"
		child.DisableFlagsInUseLine = true
		return child
	}
	return c
}

func TestTemplateRenderingInheritance(t *testing.T) {
	parent := &Command{Use: "parent"}
	child := &Command{Use: "child", Version: "1"}
	parent.AddCommand(child)
	parent.SetUsageTemplate("parent usage: {{.Name}}\n")
	parent.SetHelpTemplate("parent help: {{.Name}}\n")
	parent.SetVersionTemplate("parent version: {{.Name}} {{.Version}}\n")

	check := func(kind, want string) {
		t.Helper()
		var out bytes.Buffer
		var err error
		switch kind {
		case "usage":
			err = child.renderUsage(&out)
		case "help":
			err = child.renderHelp(&out)
		case "version":
			err = child.renderVersion(&out)
		}
		if err != nil {
			t.Fatal(err)
		}
		if out.String() != want {
			t.Fatalf("%s: got %q, want %q", kind, out.String(), want)
		}
	}
	check("usage", "parent usage: child\n")
	check("help", "parent help: child\n")
	check("version", "parent version: child 1\n")

	child.SetUsageTemplate("child usage\n")
	child.SetHelpTemplate("child help\n")
	child.SetVersionTemplate("child version\n")
	check("usage", "child usage\n")
	check("help", "child help\n")
	check("version", "child version\n")

	child.SetUsageTemplate("")
	child.SetHelpTemplate("")
	child.SetVersionTemplate("")
	check("usage", "parent usage: child\n")
	check("help", "parent help: child\n")
	check("version", "parent version: child 1\n")

	parent.SetUsageTemplate("")
	parent.SetHelpTemplate("")
	parent.SetVersionTemplate("")
	for _, kind := range []string{"usage", "help", "version"} {
		var want bytes.Buffer
		var text string
		switch kind {
