		fmt.Fprintf(&b, "\n\nExamples:\n%s", c.Example)
	}
	if c.HasAvailableSubCommands() {
		commands := c.Commands()
		writeCommand := func(cmd *Command) {
			fmt.Fprintf(&b, "\n  %s %s", rpad(cmd.Name(), cmd.NamePadding()), cmd.Short)
		}
		available := func(cmd *Command) bool {
			return cmd.IsAvailableCommand() || cmd.Name() == "help"
		}
		if len(c.Groups()) == 0 {
			b.WriteString("\n\nAvailable Commands:")
			for _, cmd := range commands {
				if available(cmd) {
					writeCommand(cmd)
				}
			}
		} else {
			for _, group := range c.Groups() {
				fmt.Fprintf(&b, "\n\n%s", group.Title)
				for _, cmd := range commands {
					if cmd.GroupID == group.ID && available(cmd) {
						writeCommand(cmd)
					}
				}
			}
			if !c.AllChildCommandsHaveGroup() {
				b.WriteString("\n\nAdditional Commands:")
				for _, cmd := range commands {
					if cmd.GroupID == "" && available(cmd) {
						writeCommand(cmd)
					}
				}
			}
		}
	}
	if c.HasAvailableLocalFlags() {
		fmt.Fprintf(&b, "\n\nFlags:\n%s", trimRightSpace(c.LocalFlags().FlagUsages()))
	}
	if c.HasAvailableInheritedFlags() {
		fmt.Fprintf(&b, "\n\nGlobal Flags:\n%s", trimRightSpace(c.InheritedFlags().FlagUsages()))
	}
	if c.HasHelpSubCommands() {
		b.WriteString("\n\nAdditional help topics:")
		for _, cmd := range c.Commands() {
			if cmd.IsAdditionalHelpTopicCommand() {
				fmt.Fprintf(&b, "\n  %s %s", rpad(cmd.CommandPath(), cmd.CommandPathPadding()), cmd.Short)
			}
		}
	}
	if c.HasAvailableSubCommands() {
		fmt.Fprintf(&b, "\n\nUse %q for more information about a command.", c.CommandPath()+" [command] --help")
	}
	b.WriteByte('\n')
	_, err := w.Write(b.Bytes())
	return err
}

func defaultHelpFunc(w io.Writer, c *Command) error {
	description := c.Long
	if description == "" {
		description = c.Short
	}
	if description != "" {
		if _, err := fmt.Fprintf(w, "%s\n\n", trimRightSpace(description)); err != nil {
			return err
		}
	}
	if c.Runnable() || c.HasSubCommands() {
		_, err := io.WriteString(w, c.UsageString())
		return err
	}
	return nil
}

func defaultVersionFunc(w io.Writer, c *Command) error {
	if name := c.Name(); name != "" {
		_, err := fmt.Fprintf(w, "%s version %s\n", name, c.Version)
		return err
	}
	_, err := fmt.Fprintf(w, "version %s\n", c.Version)
	return err
}

