func TestDefaultFormattersMatchTemplates(t *testing.T) {
	fixtures := []struct {
		name string
		make func() *Command
	}{
		{"empty", func() *Command { return &Command{} }},
		{"description", func() *Command {
			return &Command{Use: "root", Short: "Short description.  \n", Long: "Long description.  \n"}
		}},
		{"runnable", func() *Command {
			return &Command{Use: "root [arg]", Run: func(*Command, []string) {}}
		}},
		{"commands", func() *Command { return formatterTestCommand(false, false) }},
		{"groups", func() *Command { return formatterTestCommand(true, false) }},
		{"additional commands", func() *Command { return formatterTestCommand(true, true) }},
	}
	for _, fixture := range fixtures {
		t.Run(fixture.name, func(t *testing.T) {
			c := fixture.make()
			c.Version = "1.2.3"
			c.mergePersistentFlags()
			checks := []struct {
				name     string
				template string
				format   func(io.Writer, *Command) error
			}{
				{"usage", c.UsageTemplate(), defaultUsageFunc},
				{"help", c.HelpTemplate(), defaultHelpFunc},
				{"version", c.VersionTemplate(), defaultVersionFunc},
			}
			for _, check := range checks {
				t.Run(check.name, func(t *testing.T) {
					var want, got bytes.Buffer
					if err := tmpl(&want, check.template, c); err != nil {
						t.Fatal(err)
					}
					if err := check.format(&got, c); err != nil {
						t.Fatal(err)
					}
					if got.String() != want.String() {
						t.Fatalf("output mismatch:\nwant: %q\n got: %q", want.String(), got.String())
					}
				})
			}
		})
	}
}

func formatterTestCommand(grouped, additional bool) *Command {
	parent := &Command{Use: "parent"}
	parent.PersistentFlags().Bool("global", false, "global flag")
	c := &Command{
		Use: "root [arg]", Short: "Short description", Long: "Long description\n\n",
		Aliases: []string{"first", "second"}, Example: "  parent root example",
		Run: func(*Command, []string) {},
	}
	parent.AddCommand(c)
	c.Flags().String("local", "", "local flag")
	alpha := &Command{Use: "alpha", Short: "Alpha command", Run: func(*Command, []string) {}}
	beta := &Command{Use: "beta", Short: "Beta command", Run: func(*Command, []string) {}}
	help := &Command{Use: "help", Short: "Help command", Run: func(*Command, []string) {}}
	topic := &Command{Use: "topic", Short: "Additional documentation"}
	hidden := &Command{Use: "hidden", Hidden: true, Run: func(*Command, []string) {}}
	deprecated := &Command{Use: "deprecated", Deprecated: "use alpha", Run: func(*Command, []string) {}}
	if grouped {
		c.AddGroup(&Group{ID: "first", Title: "First group:"}, &Group{ID: "second", Title: "Second group:"})
		alpha.GroupID = "first"
		beta.GroupID = "second"
		help.GroupID = "first"
		topic.GroupID = "second"
		hidden.GroupID = "second"
		deprecated.GroupID = "second"
		if additional {
			beta.GroupID = ""
		}
	}
	c.AddCommand(alpha, beta, help, topic, hidden, deprecated)
	return c
}

func TestTemplateFormatterInheritanceAndReset(t *testing.T) {
	checks := []struct {
		name   string
		set    func(*Command, string)
		format func(*Command) func(io.Writer, *Command) error
	}{
		{"usage", (*Command).SetUsageTemplate, (*Command).usageTemplateFunc},
		{"help", (*Command).SetHelpTemplate, (*Command).helpTemplateFunc},
		{"version", (*Command).SetVersionTemplate, (*Command).versionTemplateFunc},
	}
	for _, check := range checks {
		t.Run(check.name, func(t *testing.T) {
			parent := &Command{Use: "parent"}
			child := &Command{Use: "child"}
			parent.AddCommand(child)
			render := func() string {
				var b bytes.Buffer
				if err := check.format(child)(&b, child); err != nil {
					t.Fatal(err)
				}
				return b.String()
			}
			original := render()
			check.set(parent, "parent: {{.Name}}")
			if got := render(); got != "parent: child" {
				t.Fatalf("inherited template: %q", got)
			}
			check.set(child, "child: {{.Name}}")
			if got := render(); got != "child: child" {
				t.Fatalf("child template: %q", got)
			}
			check.set(child, "")
			if got := render(); got != "parent: child" {
				t.Fatalf("reset child template: %q", got)
			}
			check.set(parent, "")
			if got := render(); got != original {
				t.Fatalf("reset parent template: want %q, got %q", original, got)
			}
		})
	}
}

