func TestDeadcodeElimination(t *testing.T) {
	if testing.Short() {
		t.Skip("builds executable fixtures")
	}
	goTool, err := exec.LookPath("go")
	if err != nil {
		t.Skip("go tool unavailable")
	}
	const source = `package main

import (
	"fmt"
	"reflect"

	"github.com/spf13/cobra"
)

type deadcode struct{}

//go:noinline
func (deadcode) CobraDeadcodeSentinel() {
	fmt.Println("otherwise unreachable method")
}

func main() {
	// Keep the type's runtime metadata reachable. Template execution causes
	// exported methods on reachable types to be retained by the linker.
	fmt.Println(reflect.TypeOf(deadcode{}).Name())
	c := &cobra.Command{Use: "example", Version: "1.0"}
	CUSTOMIZE
	if err := c.Execute(); err != nil {
		panic(err)
	}
}
`
	checks := []struct {
		name      string
		customize string
		retained  bool
	}{
		{"default", "", false},
		{"usage template", "c.SetUsageTemplate(c.UsageTemplate())", true},
		{"help template", "c.SetHelpTemplate(c.HelpTemplate())", true},
		{"version template", "c.SetVersionTemplate(c.VersionTemplate())", true},
		{"custom functions", `c.SetUsageFunc(func(*cobra.Command) error { return nil })
	c.SetHelpFunc(func(*cobra.Command, []string) {})`, false},
	}
	for _, check := range checks {
		t.Run(check.name, func(t *testing.T) {
			dir := t.TempDir()
			filename := filepath.Join(dir, "main.go")
			program := strings.Replace(source, "CUSTOMIZE", check.customize, 1)
			if err := ioutil.WriteFile(filename, []byte(program), 0600); err != nil {
				t.Fatal(err)
			}
			binary := filepath.Join(dir, "example.exe")
			build := exec.Command(goTool, "build", "-ldflags=-s=false -w=false", "-o", binary, filename)
			if output, err := build.CombinedOutput(); err != nil {
				t.Fatalf("build: %v\n%s", err, output)
			}
			output, err := exec.Command(goTool, "tool", "nm", binary).CombinedOutput()
			if err != nil {
				t.Fatalf("nm: %v\n%s", err, output)
			}
			retained := bytes.Contains(output, []byte("main.deadcode.CobraDeadcodeSentinel"))
			if retained != check.retained {
				t.Fatalf("exported dead method retained: got %v, want %v", retained, check.retained)
			}
		})
	}
}

