func TestBashV2ActiveHelpDisplay(t *testing.T) {
	bash, err := exec.LookPath("bash")
	if err != nil {
		t.Skip("bash is unavailable")
	}

	var generated bytes.Buffer
	genBashComp(&generated, "activehelptest", true)

	tests := []struct {
		name        string
		compType    string
		replies     string
		help        string
		want        string
		wantReplies string
	}{
		{
			name:        "first tab defers help",
			compType:    "9",
			replies:     `("unset" "use")`,
			help:        `("Command help" "Additional help")`,
			wantReplies: "<unset><use>",
		},
		{
			name:        "listing displays help and delimiter",
			compType:    "63",
			replies:     `("unset" "use")`,
			help:        `("Command help" "Additional help")`,
			want:        "\nCommand help\nAdditional help\n--",
			wantReplies: "<unset><use>",
		},
		{
			name:     "help without choices has no delimiter",
			compType: "9",
			replies:  `()`,
			help:     `("Command help")`,
			want:     "\nCommand help\n\nactivehelptest u",
		},
		{
			name:        "single completion retains immediate help",
			compType:    "9",
			replies:     `("use")`,
			help:        `("Command help")`,
			want:        "\nCommand help\n\nactivehelptest u",
			wantReplies: "<use>",
		},
		{
			name:        "listing without help has no delimiter",
			compType:    "63",
			replies:     `("unset" "use")`,
			help:        `()`,
			wantReplies: "<unset><use>",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			// Stub completion acquisition and formatting to exercise the display
			// logic independently of installed bash-completion helpers.
			script := generated.String() + `
__activehelptest_extract_activeHelp() {
    activeHelp=` + tt.help + `
}
__activehelptest_handle_completion_types() {
    COMPREPLY=` + tt.replies + `
}
__activehelptest_handle_special_char() { :; }
directive=0
cur=u
PS1=''
COMP_LINE='activehelptest u'
COMP_TYPE=` + tt.compType + `
COMPREPLY=()
__activehelptest_process_completion_results
for reply in "${COMPREPLY[@]}"; do
    printf '<%s>' "$reply" >&2
done
`
			cmd := exec.Command(bash, "--noprofile", "--norc")
			cmd.Stdin = strings.NewReader(script)
			var stdout, stderr bytes.Buffer
			cmd.Stdout = &stdout
			cmd.Stderr = &stderr
			if err := cmd.Run(); err != nil {
				t.Fatalf("bash failed: %v\n%s", err, stderr.String())
			}
			if got := stdout.String(); got != tt.want {
				t.Errorf("ActiveHelp output = %q, want %q", got, tt.want)
			}
			if got := stderr.String(); got != tt.wantReplies {
				t.Errorf("completion replies = %q, want %q", got, tt.wantReplies)
			}
		})
	}
}

