package cobra

import "testing"

func TestResetTemplates(t *testing.T) {
	tests := []struct {
		name string
		set  func(*Command, string)
		get  func(*Command) string
	}{
		{"usage", (*Command).SetUsageTemplate, (*Command).UsageTemplate},
		{"help", (*Command).SetHelpTemplate, (*Command).HelpTemplate},
		{"version", (*Command).SetVersionTemplate, (*Command).VersionTemplate},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			root := &Command{Use: "root"}
			child := &Command{Use: "child"}
			root.AddCommand(child)
			defaultTemplate := tt.get(root)

			check := func(cmd *Command, want string) {
				t.Helper()
				if got := tt.get(cmd); got != want {
					t.Fatalf("%s template = %q, want %q", cmd.Name(), got, want)
				}
			}

			tt.set(root, "parent template")
			check(root, "parent template")
			check(child, "parent template")

			tt.set(child, "child template")
			check(child, "child template")

			// Clearing a child's template restores inheritance.
			tt.set(child, "")
			check(child, "parent template")

			// Clearing the root's template restores the built-in default.
			tt.set(root, "")
			check(root, defaultTemplate)
			check(child, defaultTemplate)

			// Resetting an already cleared template is safe.
			tt.set(root, "")
			tt.set(child, "")
			check(root, defaultTemplate)
			check(child, defaultTemplate)
		})
	}
}

