func TestResetTemplates(t *testing.T) {
	tests := []struct {
		name string
		set  func(*Command, string)
		get  func(*Command) string
	}{
		{"usage", (*Command).SetUsageTemplate, (*Command).UsageTemplate},
		{"help", (*Command).SetHelpTemplate, (*Command).HelpTemplate},
		{"version", (*Command).SetVersionTemplate, (*Command).VersionTemplate},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			root := &Command{Use: "root"}
			child := &Command{Use: "child"}
			root.AddCommand(child)
			wantDefault := tt.get(&Command{})

			tt.set(root, "parent template")
			tt.set(child, "child template")
			if got := tt.get(child); got != "child template" {
				t.Fatalf("custom template = %q, want %q", got, "child template")
			}

			tt.set(child, "")
			if got := tt.get(child); got != "parent template" {
				t.Fatalf("reset child template = %q, want %q", got, "parent template")
			}

			tt.set(root, "")
			if got := tt.get(root); got != wantDefault {
				t.Fatalf("reset root template = %q, want %q", got, wantDefault)
			}
			if got := tt.get(child); got != wantDefault {
				t.Fatalf("inherited default template = %q, want %q", got, wantDefault)
			}

			tt.set(root, "replacement template")
			if got := tt.get(child); got != "replacement template" {
				t.Fatalf("inherited replacement template = %q, want %q", got, "replacement template")
			}
		})
	}
}

// SetUsageTemplate sets the usage template. An empty string restores the
