func TestDefaultCompletionCommandRootArguments(t *testing.T) {
	for _, traverse := range []bool{false, true} {
		for _, args := range [][]string{
			{},
			{"first", "second"},
			{"--flag", "first"},
		} {
			var received []string
			called := false
			root := &Command{
				Use:              "program",
				TraverseChildren: traverse,
				Run: func(cmd *Command, args []string) {
					called = true
					received = append([]string(nil), args...)
				},
			}
			root.Flags().Bool("flag", false, "a flag")
			root.SetArgs(args)
			root.SetOut(new(bytes.Buffer))
			root.SetErr(new(bytes.Buffer))
			if _, err := root.ExecuteC(); err != nil {
				t.Fatalf("TraverseChildren=%v, args=%v: %v", traverse, args, err)
			}
			if !called {
				t.Fatalf("TraverseChildren=%v, args=%v: root was not executed", traverse, args)
			}
			want := args
			if len(want) > 0 && want[0] == "--flag" {
				want = want[1:]
			}
			if strings.Join(received, "\x00") != strings.Join(want, "\x00") {
				t.Fatalf("got arguments %v, want %v", received, want)
			}
			if root.HasSubCommands() {
				t.Fatal("default completion command changed a root-only program into a program with subcommands")
			}
		}
	}
}

