func TestDefaultCompletionCmdWithoutSubcommands(t *testing.T) {
	tests := []struct {
		name       string
		args       []string
		disabled   bool
		wantRun    bool
		wantArgs   string
		wantOutput string
		wantScript bool
	}{
		{
			name:    "root arguments",
			args:    []string{"first", "second"},
			wantRun: true,
			wantArgs: "first,second",
		},
		{
			name:    "root flag and argument",
			args:    []string{"--value=test", "first"},
			wantRun: true,
			wantArgs: "first",
		},
		{
			name:     "disabled completion remains an argument",
			args:     []string{"completion", "bash"},
			disabled: true,
			wantRun:  true,
			wantArgs: "completion,bash",
		},
		{
			name:       "complete first argument",
			args:       []string{ShellCompNoDescRequestCmd, "v"},
			wantOutput: "value\n:4\n",
		},
		{
			name:       "complete subsequent argument",
			args:       []string{ShellCompNoDescRequestCmd, "first", "v"},
			wantArgs:   "first",
			wantOutput: "value\n:4\n",
		},
		{
			name:       "complete flag",
			args:       []string{ShellCompNoDescRequestCmd, "--val"},
			wantOutput: "--value\n:4\n",
		},
		{
			name:       "complete completion shells",
			args:       []string{ShellCompNoDescRequestCmd, "completion", "b"},
			wantOutput: "bash\n:4\n",
		},
		{
			name:       "complete completion shell arguments",
			args:       []string{ShellCompNoDescRequestCmd, "completion", "bash", ""},
			wantOutput: ":4\n",
		},
	}
	for _, shell := range []string{"bash", "zsh", "fish", "powershell"} {
		tests = append(tests, struct {
			name       string
			args       []string
			disabled   bool
			wantRun    bool
			wantArgs   string
			wantOutput string
			wantScript bool
		}{
			name:       "generate " + shell,
			args:       []string{"completion", shell},
			wantScript: true,
		})
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			var output bytes.Buffer
			var ran bool
			var receivedArgs string
			root := &Command{
				Use: "test",
				Run: func(cmd *Command, args []string) {
					ran = true
					receivedArgs = strings.Join(args, ",")
				},
				ValidArgsFunction: func(cmd *Command, args []string, toComplete string) ([]Completion, ShellCompDirective) {
					receivedArgs = strings.Join(args, ",")
					return []Completion{"value"}, ShellCompDirectiveNoFileComp
				},
			}
			root.CompletionOptions.DisableDefaultCmd = tt.disabled
			root.Flags().String("value", "", "")
			root.SetOut(&output)
			root.SetErr(new(bytes.Buffer))
			root.SetArgs(tt.args)

			if err := root.Execute(); err != nil {
				t.Fatalf("Execute() failed: %v", err)
			}
			if ran != tt.wantRun {
				t.Errorf("root ran = %v, want %v", ran, tt.wantRun)
			}
			if receivedArgs != tt.wantArgs {
				t.Errorf("arguments = %q, want %q", receivedArgs, tt.wantArgs)
			}
			if tt.wantScript {
				if output.Len() == 0 {
					t.Fatal("expected a completion script")
				}
			} else if output.String() != tt.wantOutput {
				t.Errorf("output = %q, want %q", output.String(), tt.wantOutput)
			}
		})
	}
}

