// Add to Command. A pointer distinguishes an unset value from an explicit
// ShellCompDirectiveDefault, whose value is zero.
defaultCompletionDirective *ShellCompDirective

// SetCompletionDirective sets the default shell completion directive for this
// command and its subcommands. A subcommand can override the inherited default
// by calling SetCompletionDirective itself, including with
// ShellCompDirectiveDefault.
//
// Directives returned by custom argument or flag completion functions take
// precedence over this default.
func (c *Command) SetCompletionDirective(directive ShellCompDirective) {
	c.defaultCompletionDirective = &directive
}

func (c *Command) getCompletionDirective() ShellCompDirective {
	for cmd := c; cmd != nil; cmd = cmd.Parent() {
		if cmd.defaultCompletionDirective != nil {
			return *cmd.defaultCompletionDirective
		}
	}
	return ShellCompDirectiveDefault
}

// In getCompletions, after resolving finalCmd, replace the initialization of
// its fallback directive:
//
// directive := ShellCompDirectiveDefault
//
// with:
directive := finalCmd.getCompletionDirective()

// Keep explicit directives from built-in completion paths and assignments
// from custom completion callbacks unchanged. The default is a fallback,
// not a bitmask to OR into callback results.

// Add bytes, fmt, strings, and testing to the imports if absent.

func TestDefaultCompletionDirectiveInheritance(t *testing.T) {
	root := &Command{Use: "root"}
	child := &Command{Use: "child"}
	grandchild := &Command{Use: "grandchild"}
	root.AddCommand(child)
	child.AddCommand(grandchild)

	if got := grandchild.getCompletionDirective(); got != ShellCompDirectiveDefault {
		t.Fatalf("unset directive = %v, want default", got)
	}

	root.SetCompletionDirective(ShellCompDirectiveNoFileComp)
	if got := grandchild.getCompletionDirective(); got != ShellCompDirectiveNoFileComp {
		t.Fatalf("inherited directive = %v, want NoFileComp", got)
	}

	child.SetCompletionDirective(ShellCompDirectiveDefault)
	if got := grandchild.getCompletionDirective(); got != ShellCompDirectiveDefault {
		t.Fatalf("explicit default = %v, want default", got)
	}

	grandchild.SetCompletionDirective(ShellCompDirectiveNoSpace | ShellCompDirectiveNoFileComp)
	want := ShellCompDirectiveNoSpace | ShellCompDirectiveNoFileComp
	if got := grandchild.getCompletionDirective(); got != want {
		t.Fatalf("local directive = %v, want %v", got, want)
	}

	root.SetCompletionDirective(ShellCompDirectiveKeepOrder)
	if got := root.getCompletionDirective(); got != ShellCompDirectiveKeepOrder {
		t.Fatalf("updated directive = %v, want KeepOrder", got)
	}
	if got := child.getCompletionDirective(); got != ShellCompDirectiveDefault {
		t.Fatalf("child override changed to %v", got)
	}
}

