	for _, noDescriptions := range []bool{false, true} {
		for _, custom := range []bool{false, true} {
			name := fmt.Sprintf("noDescriptions=%t/custom=%t", noDescriptions, custom)
			t.Run(name, func(t *testing.T) {
				root := &Command{Use: "root"}
				root.SetCompletionDirective(ShellCompDirectiveNoFileComp)
				child := &Command{
					Use: "child",
					Run: func(*Command, []string) {},
				}
				want := ShellCompDirectiveNoFileComp
				if custom {
					child.ValidArgsFunction = func(*Command, []string, string) ([]string, ShellCompDirective) {
						return []string{"choice"}, ShellCompDirectiveDefault
					}
					want = ShellCompDirectiveDefault
				}
				root.AddCommand(child)

				request := ShellCompRequestCmd
				if noDescriptions {
					request = ShellCompNoDescRequestCmd
				}
				var out bytes.Buffer
				root.SetOut(&out)
				root.SetErr(&bytes.Buffer{})
				root.SetArgs([]string{request, "child", ""})
				if err := root.Execute(); err != nil {
					t.Fatal(err)
				}
				if suffix := fmt.Sprintf(":%d\n", want); !strings.HasSuffix(out.String(), suffix) {
					t.Fatalf("completion output = %q, want suffix %q", out.String(), suffix)
				}
			})
		}
	}
