func TestDefaultShellCompDirective(t *testing.T) {
	tests := []struct {
		name             string
		configure        func(root, child, grandchild *Command)
		args             []string
		want             ShellCompDirective
	}{
		{
			name: "unchanged default",
			args: []string{""},
			want: ShellCompDirectiveDefault,
		},
		{
			name: "command default",
			configure: func(root, child, grandchild *Command) {
				root.SetDefaultShellCompDirective(ShellCompDirectiveNoFileComp)
			},
			args: []string{""},
			want: ShellCompDirectiveNoFileComp,
		},
		{
			name: "inherited through multiple levels",
			configure: func(root, child, grandchild *Command) {
				root.SetDefaultShellCompDirective(ShellCompDirectiveNoFileComp)
			},
			args: []string{"child", "grandchild", ""},
			want: ShellCompDirectiveNoFileComp,
		},
		{
			name: "nearest ancestor wins",
			configure: func(root, child, grandchild *Command) {
				root.SetDefaultShellCompDirective(ShellCompDirectiveNoFileComp)
				child.SetDefaultShellCompDirective(ShellCompDirectiveNoSpace | ShellCompDirectiveKeepOrder)
			},
