// Add to the Command struct:

	// defaultShellCompDirective overrides the inherited completion directive.
	// A pointer distinguishes an explicit ShellCompDirectiveDefault from an unset value.
	defaultShellCompDirective *ShellCompDirective

// SetDefaultShellCompDirective sets the default shell completion directive for
// this command and its subcommands. Subcommands can override the inherited
// default by calling this method. Directives returned by completion functions
// take precedence over this default.
func (c *Command) SetDefaultShellCompDirective(directive ShellCompDirective) {
	c.defaultShellCompDirective = &directive
}

func (c *Command) getDefaultShellCompDirective() ShellCompDirective {
	for cmd := c; cmd != nil; cmd = cmd.Parent() {
		if cmd.defaultShellCompDirective != nil {
			return *cmd.defaultShellCompDirective
		}
	}
	return ShellCompDirectiveDefault
}

