func TestFishCompletionArgumentQuoting(t *testing.T) {
	fish, err := exec.LookPath("fish")
	if err != nil {
		t.Skip("fish is not installed")
	}

	quote := func(s string) string {
		s = strings.ReplaceAll(s, `\`, `\\`)
		s = strings.ReplaceAll(s, "'", `\'`)
		return "'" + s + "'"
	}

	tests := []struct {
		name string
		args []string
		last string
	}{
		{"wildcard", []string{"cobra-unmatched-wildcard-*"}, "partial"},
		{"leading dashes", []string{"--style=literal*", "--", "--help"}, "--partial*"},
		{"special characters", []string{"two words", "it's literal", `a\b`, "a;b", "(literal)"}, "partial"},
		{"no previous arguments", nil, "partial*"},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			var script bytes.Buffer
			cmd := &Command{Use: "cobra-quote-test"}
			if err := cmd.GenFishCompletion(&script, true); err != nil {
				t.Fatal(err)
			}

			script.WriteString("\nset -g __cobra_test_args")
			for _, arg := range tt.args {
				script.WriteString(" " + quote(arg))
			}
			script.WriteString("\nset -g __cobra_test_last_arg " + quote(tt.last) + "\n")
			script.WriteString(`
function commandline
    switch $argv[1]
        case -opc
            printf '%s\n' cobra-quote-test $__cobra_test_args
        case -ct
            printf '%s\n' "$__cobra_test_last_arg"
    end
end

function cobra-quote-test
    printf '%s\n' $argv
    printf ':0\n'
end

__cobra_quote_test_perform_completion
`)

			output, err := exec.Command(fish, "--no-config", "-c", script.String()).CombinedOutput()
			if err != nil {
				t.Fatalf("fish completion failed: %v\n%s", err, output)
			}
			want := ShellCompRequestCmd + "\n"
			for _, arg := range tt.args {
				want += arg + "\n"
			}
			want += tt.last + "\n:0\n"
			if string(output) != want {
				t.Fatalf("completion output = %q, want %q", output, want)
			}
		})
	}
}

