func TestFishCompletionEscapesArguments(t *testing.T) {
	fish, err := exec.LookPath("fish")
	if err != nil {
		t.Skip("fish is not installed")
	}

	for _, includeDesc := range []bool{true, false} {
		name := "with descriptions"
		requestCmd := ShellCompRequestCmd
		if !includeDesc {
			name = "without descriptions"
			requestCmd = ShellCompNoDescRequestCmd
		}

		t.Run(name, func(t *testing.T) {
			var script bytes.Buffer
			script.WriteString(`
function cobra_quote_test
    if test (count $argv) -ne 5
        return 1
    end
    if test "$argv[1]" != '` + requestCmd + `'
        return 1
    end
    if test "$argv[2]" != 'cobra-no-match-*'
        return 1
    end
    if test "$argv[3]" != '--style=var'
        return 1
    end
    if test "$argv[4]" != 'two words'
        return 1
    end
    if test -n "$argv[5]"
        return 1
    end
    printf '%s\n' cobra_quote_ok :4
end
`)
			cmd := &Command{Use: "cobra_quote_test"}
			if err := cmd.GenFishCompletion(&script, includeDesc); err != nil {
				t.Fatal(err)
			}
			script.WriteString(`
complete --do-complete "cobra_quote_test 'cobra-no-match-*' --style=var 'two words' "
`)

			fishCmd := exec.Command(fish, "--no-config", "-c", script.String())
			// Ensure the wildcard cannot match a file.
