			output, err := fishCmd.CombinedOutput()
			if err != nil {
				t.Fatalf("fish completion failed: %v\n%s", err, output)
			}
			if !strings.Contains(string(output), "cobra_quote_ok") {
				t.Fatalf("completion did not receive the original arguments: %s", output)
			}
		})
	}
}

