func TestGetCompletionsDoesNotMutateArgs(t *testing.T) {
	for _, traverseChildren := range []bool{false, true} {
		name := "Find"
		if traverseChildren {
			name = "Traverse"
		}
		t.Run(name, func(t *testing.T) {
			root := &Command{Use: "root", TraverseChildren: traverseChildren}
			original := []string{"child", "value", "partial", "untouched"}
			want := append([]string(nil), original...)
			checkOriginal := func() {
				t.Helper()
				for i := range want {
					if original[i] != want[i] {
						t.Errorf("caller argument %d = %q, want %q", i, original[i], want[i])
					}
				}
			}

			called := false
			child := &Command{
				Use: "child",
				ValidArgsFunction: func(cmd *Command, args []string, toComplete string) ([]Completion, ShellCompDirective) {
					called = true
					checkOriginal()
					if len(args) != 1 || args[0] != "value" {
						t.Errorf("completion args = %v, want [value]", args)
					}
					if toComplete != "partial" {
						t.Errorf("toComplete = %q, want partial", toComplete)
					}
					return nil, ShellCompDirectiveNoFileComp
				},
			}
			root.AddCommand(child)

			// Leave spare capacity and retain the incomplete argument in the
			// caller's backing array, as with os.Args or SetArgs.
			_, _, _, err := root.getCompletions(original[:3])
			if err != nil {
				t.Fatal(err)
			}
			if !called {
				t.Fatal("ValidArgsFunction was not called")
			}
			checkOriginal()
		})
	}
}

