// UniqueArgs returns an error if there are duplicate positional arguments.
func UniqueArgs(cmd *Command, args []string) error {
	seen := make(map[string]struct{}, len(args))
	for _, arg := range args {
		if _, ok := seen[arg]; ok {
			return fmt.Errorf("duplicate argument %q for %q", arg, cmd.CommandPath())
		}
		seen[arg] = struct{}{}
	}
	return nil
}

func TestUniqueArgs(t *testing.T) {
	tests := []struct {
		name string
		args []string
		want string
	}{
		{name: "nil arguments"},
		{name: "empty arguments", args: []string{}},
		{name: "single argument", args: []string{"one"}},
		{name: "unique arguments", args: []string{"one", "two", "three"}},
		{name: "case sensitive", args: []string{"one", "One"}},
		{name: "single empty argument", args: []string{""}},
		{
			name: "adjacent duplicate",
			args: []string{"one", "one"},
			want: `duplicate argument "one" for "test"`,
		},
		{
			name: "nonadjacent duplicate",
			args: []string{"one", "two", "one"},
			want: `duplicate argument "one" for "test"`,
		},
		{
			name: "first duplicate wins",
			args: []string{"one", "two", "two", "one"},
			want: `duplicate argument "two" for "test"`,
		},
		{
			name: "duplicate empty argument",
			args: []string{"", ""},
			want: `duplicate argument "" for "test"`,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			cmd := &Command{Use: "test"}
			err := UniqueArgs(cmd, tt.args)
			if tt.want == "" {
				if err != nil {
					t.Fatalf("UniqueArgs() returned unexpected error: %v", err)
				}
				return
			}
			if err == nil {
				t.Fatalf("UniqueArgs() returned nil, want %q", tt.want)
			}
			if err.Error() != tt.want {
				t.Fatalf("UniqueArgs() error = %q, want %q", err.Error(), tt.want)
			}
		})
	}
}

