		{name: "adjacent duplicate", args: []string{"one", "one"}, want: `duplicate argument "one"`},
		{name: "nonadjacent duplicate", args: []string{"one", "two", "one"}, want: `duplicate argument "one"`},
		{name: "empty duplicate", args: []string{"", "two", ""}, want: `duplicate argument ""`},
		{name: "first duplicate", args: []string{"one", "two", "two", "one"}, want: `duplicate argument "two"`},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			original := append([]string(nil), tt.args...)
			cmd := &Command{Use: "test", Args: UniqueArgs}
			err := cmd.ValidateArgs(tt.args)
			if tt.want == "" {
				if err != nil {
					t.Fatalf("ValidateArgs() returned unexpected error: %v", err)
				}
			} else if err == nil || err.Error() != tt.want {
				t.Fatalf("ValidateArgs() error = %v, want %q", err, tt.want)
			}
			for i, arg := range original {
				if tt.args[i] != arg {
					t.Fatalf("argument %d changed: got %q, want %q", i, tt.args[i], arg)
				}
			}
		})
	}
}

func TestUniqueArgsWithMatchAll(t *testing.T) {
	cmd := &Command{
		Use:  "test",
		Args: MatchAll(MinimumNArgs(2), UniqueArgs),
	}
	if err := cmd.ValidateArgs([]string{"one", "two"}); err != nil {
		t.Fatalf("ValidateArgs() returned unexpected error: %v", err)
	}
	if err := cmd.ValidateArgs([]string{"one"}); err == nil {
		t.Fatal("ValidateArgs() accepted too few arguments")
	}
	if err := cmd.ValidateArgs([]string{"one", "one"}); err == nil || err.Error() != `duplicate argument "one"` {
		t.Fatalf("ValidateArgs() error = %v, want duplicate argument error", err)
	}
}

