struct close_result {
  CURL *easy;
  size_t received;
  int failed;
};

static size_t close_write(char *buffer, size_t size, size_t nmemb,
                          void *userdata)
{
  static const unsigned char expected[] = { 0x03, 0xe8, 'b', 'y', 'e' };
  struct close_result *result = userdata;
  const struct curl_ws_frame *meta = curl_ws_meta(result->easy);
  size_t len = size * nmemb;

  if(!meta || !(meta->flags & CURLWS_CLOSE) ||
     result->received > sizeof(expected) ||
     len > sizeof(expected) - result->received ||
     memcmp(buffer, expected + result->received, len)) {
    result->failed = 1;
    return 0;
  }

  result->received += len;
  return len;
}

CURLcode test(char *URL)
{
  struct close_result result;
  CURLcode res;

  memset(&result, 0, sizeof(result));
  res = curl_global_init(CURL_GLOBAL_ALL);
  if(res)
    return res;

  result.easy = curl_easy_init();
  if(!result.easy) {
    curl_global_cleanup();
    return CURLE_OUT_OF_MEMORY;
  }

  res = curl_easy_setopt(result.easy, CURLOPT_URL, URL);
  if(!res)
    res = curl_easy_setopt(result.easy, CURLOPT_WRITEFUNCTION, close_write);
  if(!res)
    res = curl_easy_setopt(result.easy, CURLOPT_WRITEDATA, &result);
  if(!res)
    res = curl_easy_setopt(result.easy, CURLOPT_TIMEOUT, 120L);
  if(!res)
    res = curl_easy_perform(result.easy);

  if(!res && (result.failed || result.received != 5)) {
    curl_mfprintf(stderr, "Incomplete CLOSE payload: received %zu bytes\n",
                  result.received);
    res = CURLE_RECV_ERROR;
  }

  curl_easy_cleanup(result.easy);
  curl_global_cleanup();
  return res;
}

