void jsonWriteString(FILE *stream, const char *in, bool lowercase)
{
  const unsigned char *i = (const unsigned char *)in;
  const unsigned char *in_end = i + strlen(in);
  static const char hex[] = "0123456789abcdef";
  char out[256];
  size_t used = 0;

  fputc('\"', stream);
  for(; i < in_end; i++) {
    const char *escape = NULL;
    size_t n = 1;
    unsigned char c = *i;

    /* One input byte can expand to six output bytes. */
    if(sizeof(out) - used < 6) {
      fwrite(out, 1, used, stream);
      used = 0;
    }

    switch(c) {
    case '\\':
      escape = "\\\\";
      break;
    case '\"':
      escape = "\\\"";
      break;
    case '\b':
      escape = "\\b";
      break;
    case '\f':
      escape = "\\f";
      break;
    case '\n':
      escape = "\\n";
      break;
    case '\r':
      escape = "\\r";
      break;
    case '\t':
      escape = "\\t";
      break;
    default:
      break;
    }

    if(escape) {
      memcpy(out + used, escape, 2);
      used += 2;
    }
    else if(c < 32 || (c >= 0x80 && !(n = utf8len(i, in_end)))) {
      /* Escape invalid UTF-8 bytes as ISO-8859-1. */
      memcpy(out + used, "\\u00", 4);
      used += 4;
      out[used++] = hex[c >> 4];
      out[used++] = hex[c & 0x0f];
    }
    else if(c >= 0x80) {
      memcpy(out + used, i, n);
      used += n;
      i += n - 1;
    }
    else {
      if(lowercase && c >= 'A' && c <= 'Z')
        /* Do not use tolower() since that is locale specific. */
        c |= ('a' - 'A');
      out[used++] = (char)c;
    }
  }
  if(used)
    fwrite(out, 1, used, stream);
  fputc('\"', stream);
}

